{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "ZIP polygons, drawn from a bare geoshape mark.",
  "data": {
    "name": "data"
  },
  "mark": "geoshape",
  "encoding": {
    "color": {
      "field": "zip",
      "type": "nominal",
      "legend": null
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Two geometry columns drawn as two layers.",
  "data": {
    "name": "data"
  },
  "layer": [
    {
      "mark": {
        "type": "geoshape",
        "stroke": "white",
        "strokeWidth": 0.5
      },
      "encoding": {
        "color": {
          "field": "shape_area",
          "type": "quantitative",
          "title": "Area",
          "scale": {
            "scheme": "blues"
          }
        }
      }
    },
    {
      "mark": {
        "type": "geoshape",
        "color": "#c2410c"
      },
      "encoding": {
        "shape": {
          "field": "centroid",
          "type": "geojson"
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Bar and scatter over the same frame.",
  "data": {
    "name": "data"
  },
  "vconcat": [
    {
      "mark": "bar",
      "encoding": {
        "x": {
          "field": "zip",
          "type": "nominal",
          "sort": "-y"
        },
        "y": {
          "field": "shape_area",
          "type": "quantitative",
          "aggregate": "mean"
        }
      }
    },
    {
      "mark": "point",
      "encoding": {
        "x": {
          "field": "shape_len",
          "type": "quantitative"
        },
        "y": {
          "field": "shape_area",
          "type": "quantitative"
        }
      }
    }
  ]
}
